"""Render the measured engine, acting, training, board and playing-strength receipts."""
import json,statistics,sys
from pathlib import Path
P=Path(__file__).resolve().parent
R=P/'results'
def j(p):return json.loads(p.read_text())
def pct(f):return f'{100*f:.2f}%'
def num(x):return f'{x:,.0f}'
def tab(head,rows):
    return '\n'.join(['| '+' | '.join(head)+' |','|'+'|'.join('---' for _ in head)+'|']+['| '+' | '.join(map(str,row))+' |' for row in rows])
def ci(x):return '–'.join(f'{100*v:.2f}' for v in x)+'%'
def main():
    old=j(R/'engine-comparison.json');vbench={d.name:j(d/'result.json') for d in R.glob('v-*') if (d/'result.json').exists()}
    chosen=j(R/'chosen.json');name=chosen['proof'];run=j(R/name/'result.json');newvector=name!='proof'
    proof=j(R/'proof/result.json');begin=j(R/'progression.json');ledger=j(R/chosen['ledger']);row=ledger['checkpoints'][-1]
    board=row['board_strength'];base=ledger['board_baseline'];panel=ledger['baseline_panel']
    h2h=j(R/chosen['confirmation']);screen=row['against_25772'];pair=j(R/chosen['board_test'])
    docs=[]
    def add(x):docs.append(x)
    add('# Training and vector collection on Turtle v31g')
    add(f'The selected 14,346,925-parameter parent arm completed **{run["updates"]} updates** at **{num(run["learned_s"])} learned decisions/s**, with **{pct(run["stale_share"])} stale**. The historical live path delivered 791/s with 40.7% stale. The selected checkpoint is {row["version"]:,}. [Proof]({"results/"+name}/result.json) · [Watcher record](results/{chosen["ledger"]})')
    controls={p.name:receipt for p in R.glob('cohort12x*') if (p/'result.json').exists() for receipt in [j(p/'result.json')]}
    if controls:
        add(tab(['15-core cohort test','Learned/s overall','Collected live/s','Stale','GPU'],[[n,num(v['learned_s']),num(v['collected_s']),pct(v['stale_share']),f"{v['gpu_util_mean']:.1f}%"] for n,v in sorted(controls.items())]))
    add(f'The final configuration was chosen from real-training throughput before its scores were read. The screening choice was **{chosen["winner"]}**; the 100-update proof is reported separately from the short tuning run. [Selection rule](selection.md) · [Selection receipts](results/chosen.json)')
    add('## Same-hardware engine change')
    add('The original and replacement runs use CPUs 10–15 and 17–19, 8 workers × 24 games, 1,536 padded learner rows, an 8,192-decision update target, a half-batch queue, maximum lag one, the 25,772 AdamW state and historical rates, and 50% frozen games. Each comparison has 100 updates and begins with new games. The earlier c proof logged every native battle input for an independent audit. The 16-update comparison omits that audit on both engines. The c figures here are from the uncontended final trials. The earlier busy 05:47–05:54 window contributes no baseline.')
    add(tab(['Package and trial','Learned/s','Collected live/s','Both seats/s','Games/s','Stale','GPU util'],[[k+' '+label,num(z['overall_learned_s']),num(z['delivered_s']),num(z['seat_s']),f"{z['games_s']:.2f}",pct(z['stale']),f"{z['gpu']:.1f}%"] for k,b in old.items() for label,z in [('16 updates',b['short']),('100 updates',b['proof'])]]))
    add(tab(['Profiled time share','c','g'],[[k,*[f"{old[e]['profile'][k]:.1f}%" for e in ('c','g')]] for k in ['engine','encoding','inference','learner_wait','ipc_wait','control','learner_active','overlap','worker_wait']]))
    add('The first six timing rows partition coordinator wall. Learner active and simultaneous learner/inference overlap that wall. Worker waiting has its own denominator, summed worker time. Collection is completed learner-eligible seat decisions. Stale is rejected decisions divided by rejected plus learned decisions. All throughput counts include the cost of both seats, even when only one seat is learned. [Comparison and raw run locations](results/engine-comparison.json)')
    clean=j(R/'clean-window.json')
    add(f'During the final 12 × 16 proof, one CPU-only checkpoint-loading check briefly used core 16. Excluding startup and all {clean["probe_intersecting_updates"]} intersecting update intervals gives {num(clean["clean_learned_s"])} learned/s over {clean["retained_updates"]} remaining updates. The separate matched-layout and tuning trials did not overlap that check. [Timing sensitivity](results/clean-window.json)')
    add('## Engine revision and fixed opponents')
    add('The scoring and training launchers verify Python package g, revision `turtle-v31-replay-852b274e7eb2-20261123`, payload `d1a4509282965e41b92ed55021e266ca4440c86f52a9055399c5d1eba48d57a2`. The Rust wrapper, rules and shared library come from the read-only v31g pin; the library SHA-256 starts `d8cd765d898f`. The paired evaluator resolves battles in the packaged Python reference. The board recorder and collector use the pinned Rust wrapper. c, f and g have the identical gym payload `3291838d…`, public observations, native action heads, recurrence and optimizer groups. The allow-listed 25,772 initializer (originally v30) loads strictly with its saved Adam moments and four rates. No parameter transform is required to carry it to f or g. Keep the original checkpoint immutable, initialize a new run under the destination stamp, and regenerate its evaluation receipts. A literal same-run resume of a c-stamped checkpoint on g correctly fails the revision check. A strict CPU transfer check on c, f and g compared every restored parameter tensor, optimizer state and parameter group with the original. [Transfer receipts](results/transfer.json) · [New scoring config](config.py) · [Evaluator](evaluate.py)')
    add(tab(['Frozen 25,772 vs','Greedy match score','Paired bootstrap 95% CI','Paired worlds'],[[k,pct(panel[k]['score']),ci(panel[k]['ci95']),panel[k]['pairs']] for k in ('v22','v25')]))
    add('## Ranked board strength and the watcher')
    add('Each checkpoint plays 1,000 complete greedy self-play matches. Both pre-battle boards are recorded, including their order, effective stats, perk, level, consumed triggers and copied ability. Ranked fixtures are read only by the evaluator. The exact original ghost sampling order, 4,000 board pairs per turn and 8 fight seeds per pair are retained; the mutable oracle binary is replaced by an outcome adapter to the pinned library. Re-running archived greedy boards reproduced every published score in all four comparisons exactly. [Recorder](record_boards.py) · [Ghost protocol](ghost_g.py) · [Pinned ABI adapter](ghost_fights.py) · [Exact archived control](results/archived-ghost.json)')
    add(tab(['1,000 matches','T3','T5','T7','T10','T12','Mean','Recording s','Ghost CPU wall s'],[[k,*[pct(m['scores'][str(t)]) for t in (3,5,7,10,12)],pct(m['index']),m['recording_seconds'],round(j(Path(m['receipt'])).get('active_s',m['ghost_wall_s']),1)] for k,m in [('Parent',base),('Proof',board)]]))
    add('Recording seconds span self-play and file writes after loading the model. Ghost CPU wall includes reading fixture pools and all four field controls and excludes waiting for exclusive benchmark cores. The wall-clock receipts separately retain any time waiting to run on the shared benchmark hardware. Future checkpoints reuse the fixed ranked cohort and self-play seeds. The watcher writes board scores and their mean atomically beside the normal paired match and panel scores; identity is bound to checkpoint SHA, engine digest and seed. Start once with `python3 watch_g.py --once --run runs/NAME --progression /absolute/path/to/progression.json`; omit `--once` to poll. The new watcher was exercised in one-shot mode. [Watcher](watch_g.py) · [Board metric](board_metric.py) · [Ranked corpus inputs](results/fixtures.json)')
    add('## Proof of playing strength')
    add(f'The final proof scored **{pct(screen["score"])} [{ci(screen["ci95"])}]** against the initializer on 64 paired screening worlds and **{pct(h2h["score"])} [{ci(h2h["ci95"])}]** on 256 disjoint, seat-swapped confirmation worlds. A win is 1, a draw 0.5. The independent board comparison pairs the two policies on 1,000 greedy world seeds, draws 16 common field opponents per observed seat/turn × 8 battle seeds, and bootstraps whole self-play worlds 10,000 times. Its index difference is {100*pair["delta"]:+.2f} points [{100*pair["ci95"][0]:+.2f}, {100*pair["ci95"][1]:+.2f}], conditional on the fixed ranked pool. The ordinary watcher index above uses the original ghost sampling scheme. [Head-to-head confirmation](results/{chosen["confirmation"]}) · [Paired board check](results/{chosen["board_test"]})')
    if h2h['ci95'][0]>=.5 and pair['ci95'][0]>=0:add('Both independent tests clear zero-margin non-regression on these checkpoints.')
    elif h2h['ci95'][1]<.5 or pair['ci95'][1]<0:add('At least one independent interval is entirely on the worse side. The proof failed the playing-strength gate.')
    else:add('The short proof does not statistically establish zero-margin non-regression on both measures. Keep 25,772 as the reference champion.')
    if name!='proof':
        first=begin['checkpoints'][0];earlier=j(R/'proof-confirm.json')
        add(f'The separate 8 × 24 engine-change run also produced an update numbered 25,872. Its SHA-256 starts `{first["sha256"][:12]}`; the selected proof starts `{row["sha256"][:12]}`. The 8 × 24 proof scored {pct(earlier["score"])} [{ci(earlier["ci95"])}] vs 25,772 on its fresh worlds and {pct(first["board_strength"]["index"])} on the standard board index. Both runs remain in the record. [Earlier proof progression](results/progression.json) · [Earlier confirmation](results/proof-confirm.json)')
    final_profile=R/'final-profile'
    if (final_profile/'result.json').exists():
        from measure_diff import profile
        z=profile(final_profile)
        add(f'On the selected cohort layout, inference service accounted for {z["inference"]:.1f}% of coordinator wall, learner wait {z["learner_wait"]:.1f}%, engine {z["engine"]:.1f}%, encoding {z["encoding"]:.1f}% and IPC plus other control {z["ipc_wait"]+z["control"]:.1f}%. The learner was active {z["learner_active"]:.1f}% and overlapped inference for {z["overlap"]:.1f}% of wall. [Selected-layout instrumented run](results/final-profile/result.json)')
    add('## Inferred Honey Bee sales')
    bees=j(R/'bee.json');assert len(bees)==3 and all(not r['diff'] and r['real_gain']==r['engine_gain']==1 for r in bees)
    add('**3/3 turns now match, 0/3 Bees sell for two.** Two level-two Flamingos and one level-two Ant held Honey. Each was pilled; the generated level-one Bee sold for one gold. The saved shop witness now matches the entire recorded endpoint on all three turns. This was the targeted regression check. [Sale traces and gold receipts](results/bee.json)')
    add('## Vector environment and collection')
    add('All active seats share one GPU GRU bank. Each wave gathers the public observation arrays and serves one sampled forward per active policy identity. The Python stand-in parallelizes persistent scalar environments by shard; the Rust port can implement the same reset/step and output contract. Rewards, terminal bootstraps and versioned behavior log probabilities are captured before reset. Only live-seat turns enter the unchanged learner. Training and rollout overlap on separate CUDA streams, with backpressure and whole-turn lag rejection. [Vector ABI](vector_contract.md) · [Vector collector](vector_collect.py) · [Independent scalar/turn transport tests](results/turns-check.log)')
    add('The replay experiment uses every step of 64 complete sampled-parent games, 18,788 seat actions and 64 actual terminal records. It still copies every public observation, samples both policies and updates recurrent state. Actions cannot change tape outcomes. Its learner is disposable at learning rate zero. Games/s is counted at real terminal flags, with no turn cap or incentive for short games. Python games run from turn one. The long enough steady window starts after at least one cohort’s worth of completed games; whole-window rates also count initial in-flight work. [Tape receipt](results/tape/receipt.json) · [Terminal and reset accounting](results/replay-check.log)')
    rows=[]
    for k,z in vbench.items():
        t=z['steady'];rows.append([k,z['games'],num(z['mean_active_seats']),num(z['seat_s']),f"{z['games_s']:.2f}",num(t['seat_s']) if t else '—',f"{t['games_s']:.2f}" if t else '—',num(z['learned_s']),pct(z['stale_share']) if z['training'] else '—',f"{z['gpu']:.1f}%"])
    add(tab(['Run','Games in flight','Mean active seats','Seat/s','Games/s','Steady seat/s','Steady games/s','Learned/s','Stale','GPU util'],rows))
    add(tab(['Run','Actor service','Vector step','Reset','Turn storage','Learner wait/publication','Learner active (overlaps)'],[[k,*[f"{100*z['main_seconds'].get(cap,0)/z['wall']:.1f}%" for cap in ('actor','engine','reset','turn_capture','wait_publish')],f"{100*z['learner_wall']/z['wall']:.1f}%"] for k,z in vbench.items()]))
    fast=vbench['v-replay-act-4096'];paired=vbench['v-replay-act'];live=vbench['v-python-act'];tr=vbench['v-replay-train'];loose=vbench['v-replay-loose'];pr=vbench['v-python-train']
    peak=max(q['rate'] for q in j(R/'forward.json')['parent']['rows'] if 'rate' in q)
    add(f'With the engine replayed, 4,096 games in flight reached **{num(fast["seat_s"])} seat decisions/s**, {100*fast["seat_s"]/peak:.1f}% of this GPU’s independently measured parent acting ceiling. The matched 1,024-game runs with no learning reached {num(live["seat_s"])}/s on live Python and {num(paired["seat_s"])}/s on replay. Under the half-batch training queue, replay acting fell to **{num(tr["seat_s"])}/s** while the unchanged learner absorbed **{num(tr["learned_s"])}/s**, with {pct(tr["stale_share"])} stale. The coordinator spent {100*tr["main_seconds"].get("wait_publish",0)/tr["wall"]:.1f}% of wall time waiting/publishing and {100*tr["main_seconds"]["actor"]/tr["wall"]:.1f}% serving the policy. A four-batch queue tested this tradeoff directly: {num(loose["seat_s"])} seat/s, {num(loose["learned_s"])} learned/s and {pct(loose["stale_share"])} stale. Throughput with the Python engine and learning was {num(pr["seat_s"])} seat/s and {num(pr["learned_s"])} learned/s at the same 1,024-game width. [Actor-only receipts](results/v-replay-act-4096/result.json) · [Concurrent replay](results/v-replay-train/result.json) · [Larger queue](results/v-replay-loose/result.json)')
    add('The original engine-g training proof used the original nine-core layout. Vector experiments have access to CPUs 5–19 and use 12 worker processes for Python. Games per second for replay are traversed recordings. The sweep compares collector capacities and changes which games/turns reach an update. No ranked boards entered training. A 100-update continuation precedes the first periodic frozen snapshot.')
    add('## Forward-only network ceilings')
    nets=j(R/'forward.json');add(tab(['Policy','Parameters','1,024','2,048','4,096','8,192','16,384','Peak decisions/s'],[[k,f"{v['parameters']:,}",*[num(x['rate']) if 'rate' in x else 'OOM' for x in v['rows']],num(max(x.get('rate',0) for x in v['rows']))] for k,v in nets.items()]))
    length=statistics.mean(j(R/'tape/receipt.json')['seat_decisions'])
    add(f'Full sampled BF16 actor with public observations tiled from real g states. Inputs and seat memory are resident on the GPU; measurement excludes environment, host transfer and learning. Each cell is batch size divided by the median of six synchronized calls after two warm-ups. The random-weight smaller policies use model width / transformer depth / GRU width of 80/2/96, 128/4/192 and 224/5/320 respectively. Their attention head counts are 4, 4, 8, their opponent-history widths are 32, 48, 80 and feed-forward width is 4× model width. The 384/6/512 parent uses its actual checkpoint. At the measured tape mean of {length:.1f} seat decisions/game, 1,000 games/s requires about {num(1000*length)} decisions/s before learning or simulation cost. Even the 0.39M actor’s measured ceiling falls short. At 400 decisions/game the requirement is 400,000/s. No playing-strength inference follows from the smaller-network timings. [All repeated forward measurements](results/forward.json)')
    add('## Reproduction')
    add('From this directory, `./reproduce.sh results/new-proof` runs the chosen 100-update configuration. For the matched actor-only cases use `SPEED_CPUS=5-19 ./run.sh vector_collect.py --backend python --workers 12 --games 1024 --seconds 155 --out results/new-live`, or substitute `--backend replay` and another output name. Add `--train` to measure the concurrent learner. The launcher uses the pinned container digest, an 8-GiB allocator cap, read-only source mounts and an 870-second hard guard for each GPU invocation. [Proof preset](reproduce.sh) · [Launcher](run.sh) · [Raw small-network timings](results/forward.json)')
    (P/'REPORT.md').write_text('\n\n'.join(docs)+'\n')
if __name__=='__main__':main()
